#!/usr/bin/env node
/**
 * Generates the v1.0.0 planning documents from backlog.data.mjs.
 *
 *   node scripts/planning/generate-backlog.mjs           # write files
 *   node scripts/planning/generate-backlog.mjs --check   # CI: fail if generated files are stale or data is invalid
 */
import { existsSync } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../..");
const planDir = join(repoRoot, "documentation/planning/release-1.0.0");
const data = await import(pathToFileURL(join(planDir, "backlog.data.mjs")).href);
const { release, sprints, milestones, epics, stories } = data;
const impl = data.implementation ?? { default: "todo", overrides: {} };
const statusOf = (s) => impl.overrides[s.id]?.status ?? impl.default;
const noteOf = (s) => impl.overrides[s.id]?.note;
const STATUS_ICON = { done: "✅", partial: "🟡", todo: "⬜" };
const donePts = (arr) => arr.filter((s) => statusOf(s) === "done").reduce((a, s) => a + s.pts, 0);
const check = process.argv.includes("--check");

// ── Validation ───────────────────────────────────────────────────────────────────────────────
const errors = [];
const warnings = [];
const sprintIndex = new Map(sprints.map((s, i) => [s.id, i]));
const epicById = new Map(epics.map((e) => [e.id, e]));
const storyById = new Map();
const FIB = new Set([1, 2, 3, 5, 8, 13]);

for (const s of stories) {
  if (storyById.has(s.id)) errors.push(`Duplicate story id ${s.id}`);
  storyById.set(s.id, s);
  if (!epicById.has(s.epic)) errors.push(`${s.id}: unknown epic ${s.epic}`);
  if (!sprintIndex.has(s.sprint)) errors.push(`${s.id}: unknown sprint ${s.sprint}`);
  if (!FIB.has(s.pts)) errors.push(`${s.id}: points must be Fibonacci (got ${s.pts})`);
  if (s.pts > 8) warnings.push(`${s.id}: ${s.pts} points — consider splitting`);
  if (!["Must", "Should", "Could"].includes(s.pri))
    errors.push(`${s.id}: invalid priority ${s.pri}`);
  if (!s.ac?.length) errors.push(`${s.id}: missing acceptance criteria`);
}
for (const s of stories) {
  for (const d of s.deps) {
    const dep = storyById.get(d);
    if (!dep) {
      errors.push(`${s.id}: unknown dependency ${d}`);
      continue;
    }
    if (sprintIndex.get(dep.sprint) > sprintIndex.get(s.sprint)) {
      errors.push(`${s.id} (${s.sprint}) depends on ${d} scheduled later (${dep.sprint})`);
    }
    if (dep.sprint === "STRETCH" && s.sprint !== "STRETCH")
      errors.push(`${s.id} depends on stretch story ${d}`);
  }
}
const load = new Map(sprints.map((sp) => [sp.id, 0]));
for (const s of stories) load.set(s.sprint, load.get(s.sprint) + s.pts);
for (const sp of sprints) {
  if (sp.id === "STRETCH") continue;
  if (load.get(sp.id) > release.velocity.maxCommit) {
    errors.push(`${sp.id} over-committed: ${load.get(sp.id)} pts > ${release.velocity.maxCommit}`);
  }
}
if (errors.length) {
  console.error(`✖ Backlog validation failed:\n  - ${errors.join("\n  - ")}`);
  process.exit(1);
}

// ── Helpers ──────────────────────────────────────────────────────────────────────────────────
const slug = (s) =>
  s
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
/** GitHub heading anchor algorithm: lowercase, drop punctuation, spaces → hyphens. */
const ghAnchor = (h) =>
  h
    .toLowerCase()
    .replace(/[^\p{L}\p{N} _-]/gu, "")
    .replace(/ /g, "-");
const epicFile = (e) => `${e.id}-${slug(e.name)}.md`;
const storyAnchor = (s) => `${s.id.toLowerCase()}`;
const storyLink = (s, fromEpicsDir = true) =>
  `[${s.id}](${fromEpicsDir ? "" : "epics/"}${epicFile(epicById.get(s.epic))}#${storyAnchor(s)})`;
const sum = (arr) => arr.reduce((a, s) => a + s.pts, 0);
const header =
  "<!-- GENERATED by scripts/planning/generate-backlog.mjs from backlog.data.mjs — do not edit by hand. -->\n\n";
const priBadge = { Must: "🟥 Must", Should: "🟧 Should", Could: "🟦 Could" };
const committed = stories.filter((s) => s.sprint !== "STRETCH");
const total = sum(committed);

const outputs = new Map();

// ── epics/*.md ───────────────────────────────────────────────────────────────────────────────
for (const e of epics) {
  const es = stories.filter((s) => s.epic === e.id);
  const span = [...new Set(es.map((s) => s.sprint))].sort(
    (a, b) => sprintIndex.get(a) - sprintIndex.get(b),
  );
  let md = `${header}# Epic ${e.id} — ${e.name}\n\n`;
  md += `> ${e.goal}\n\n`;
  md += `| | |\n|---|---|\n`;
  md += `| Spec reference | ${e.refs.join(", ")} (spec epic letter: ${e.letter}) |\n`;
  md += `| Stories | ${es.length} · ${sum(es)} points (${["Must", "Should", "Could"].map((p) => `${es.filter((s) => s.pri === p).length} ${p}`).join(" · ")}) |\n`;
  md += `| Sprints | ${span.join(" → ")} |\n`;
  md += `| Acceptance gate | ${e.gate} |\n\n`;
  if (e.out.length) md += `**Out of scope for 1.0.0:** ${e.out.join("; ")}.\n\n`;
  md += `| Implementation | ${donePts(es)} / ${sum(es)} points done (v${impl.version}) |\n\n`;
  md += `## Stories\n\n| ID | Story | Pri | Pts | Sprint | Status | Depends on |\n|---|---|---|---|---|---|---|\n`;
  for (const s of es) {
    md += `| [${s.id}](#${storyAnchor(s)}) | ${s.title} | ${s.pri} | ${s.pts} | ${s.sprint} | ${STATUS_ICON[statusOf(s)]} ${statusOf(s)} | ${s.deps.map((d) => storyLink(storyById.get(d))).join(", ") || "—"} |\n`;
  }
  for (const s of es) {
    md += `\n---\n\n### ${s.id}\n\n**${s.title}**\n\n`;
    md += `*As a **${s.as}**, I want **${s.want}**, so that **${s.so}**.*\n\n`;
    md += `| Priority | Points | Sprint | Spec | Depends on |\n|---|---|---|---|---|\n`;
    md += `| ${priBadge[s.pri]} | ${s.pts} | ${s.sprint} | ${s.refs.join(", ")} | ${s.deps.map((d) => storyLink(storyById.get(d))).join(", ") || "—"} |\n\n`;
    const st = statusOf(s);
    md += `**Status:** ${STATUS_ICON[st]} ${st}${noteOf(s) ? ` — ${noteOf(s)}` : ""}\n\n`;
    md += `**Acceptance criteria**\n\n${s.ac.map((a) => `- [${st === "done" ? "x" : " "}] ${a}`).join("\n")}\n`;
  }
  outputs.set(join(planDir, "epics", epicFile(e)), md);
}

// ── epics/README.md ─────────────────────────────────────────────────────────────────────────
{
  let md = `${header}# v${release.version} epics\n\n`;
  md += `${epics.length} epics · ${stories.length} stories · ${total} committed points (+${sum(stories) - total} stretch).\n\n`;
  md += `**Implementation (v${impl.version}):** ${donePts(committed)} / ${total} committed points done · ${stories.filter((s) => statusOf(s) === "partial").length} partial · ${stories.filter((s) => statusOf(s) === "todo").length} todo.\n\n`;
  md += `| Epic | Name | Stories | Points | Done pts | Must | Should | Could | Sprints | Acceptance gate |\n|---|---|---|---|---|---|---|---|---|---|\n`;
  for (const e of epics) {
    const es = stories.filter((s) => s.epic === e.id);
    const span = [...new Set(es.map((s) => s.sprint))].sort(
      (a, b) => sprintIndex.get(a) - sprintIndex.get(b),
    );
    md += `| [${e.id}](${epicFile(e)}) | ${e.name} | ${es.length} | ${sum(es)} | ${donePts(es)} | ${es.filter((s) => s.pri === "Must").length} | ${es.filter((s) => s.pri === "Should").length} | ${es.filter((s) => s.pri === "Could").length} | ${span[0]}${span.length > 1 ? `–${span.at(-1)}` : ""} | ${e.gate} |\n`;
  }
  md += `\n## Epic dependency flow\n\n\`\`\`mermaid\nflowchart LR\n`;
  const edges = new Set();
  for (const s of stories)
    for (const d of s.deps) {
      const from = storyById.get(d).epic;
      if (from !== s.epic) edges.add(`  ${from} --> ${s.epic}`);
    }
  for (const e of epics) md += `  ${e.id}["${e.id} · ${e.name}"]\n`;
  md += `${[...edges].sort().join("\n")}\n\`\`\`\n`;
  outputs.set(join(planDir, "epics/README.md"), md);
}

// ── sprints.md ───────────────────────────────────────────────────────────────────────────────
{
  const cap = release.velocity.planned;
  let md = `${header}# v${release.version} sprint plan\n\n`;
  md += `Planning is in **story points only**. Capacity per sprint: **${cap} pts** (hard cap ${release.velocity.maxCommit}). Re-baseline at every sprint review using measured velocity.\n\n`;
  md += `**Implementation (v${impl.version}):** ${donePts(committed)} / ${total} committed points done.\n\n`;
  md += `## Overview\n\n| Sprint | Name | Points | Load vs capacity | Done | Milestone |\n|---|---|---|---|---|---|\n`;
  let cumulative = 0;
  const burn = [];
  for (const sp of sprints) {
    if (sp.id === "STRETCH") continue;
    const pts = load.get(sp.id);
    cumulative += pts;
    burn.push([sp.id, cumulative]);
    const ms = milestones.find((m) => m.sprint === sp.id);
    const bar =
      "█".repeat(Math.round(pts / 4)) +
      "░".repeat(Math.max(0, Math.round(release.velocity.maxCommit / 4) - Math.round(pts / 4)));
    md += `| [${sp.id}](#${ghAnchor(`${sp.id} — ${sp.name}`)}) | ${sp.name} | ${pts} / ${cap} | \`${bar}\` | ${donePts(stories.filter((s) => s.sprint === sp.id))} pts | ${ms ? `**${ms.id}** ${ms.version !== "—" ? `\`${ms.version}\` ` : ""}${ms.name}` : ""} |\n`;
  }
  md += `\n\`\`\`mermaid\nflowchart LR\n`;
  const real = sprints.filter((s) => s.id !== "STRETCH");
  for (const sp of real) {
    const ms = milestones.find((m) => m.sprint === sp.id);
    md += `  ${sp.id}["${sp.id} · ${sp.name}<br/>${load.get(sp.id)} pts"]${ms ? `:::ms` : ""}\n`;
  }
  md += `  ${real.map((s) => s.id).join(" --> ")}\n`;
  for (const m of milestones)
    md += `  ${m.sprint} -.-> ${m.id}(("${m.id}${m.version !== "—" ? ` ${m.version}` : ""}"))\n`;
  md += `  classDef ms stroke-width:2px\n\`\`\`\n\n`;
  md += `## Burn-up (points)\n\n| After sprint | Cumulative points | % of committed scope |\n|---|---|---|\n`;
  for (const [id, c] of burn) md += `| ${id} | ${c} | ${Math.round((c / total) * 100)}% |\n`;

  md += `\n## Milestones\n\n`;
  for (const m of milestones) {
    const upTo = burn.find(([id]) => id === m.sprint)?.[1] ?? 0;
    md += `### ${m.id} — ${m.name}${m.version !== "—" ? ` (\`${m.version}\`)` : ""}\n\nEnd of ${m.sprint} · ${upTo} / ${total} pts delivered\n\n${m.exit.map((x) => `- [ ] ${x}`).join("\n")}\n\n`;
  }

  for (const sp of sprints) {
    const ss = stories.filter((s) => s.sprint === sp.id);
    md += `---\n\n## ${sp.id} — ${sp.name}\n\n`;
    md +=
      sp.id === "STRETCH"
        ? `**${sum(ss)} pts** (not committed)\n\n`
        : `**${sum(ss)} / ${cap} pts committed**\n\n`;
    md += `**Sprint goal:** ${sp.goal}\n\n**Demo:** ${sp.demo}\n\n`;
    md += `| ID | Epic | Story | Pri | Pts | Status |\n|---|---|---|---|---|---|\n`;
    for (const s of ss)
      md += `| ${storyLink(s, false)} | ${s.epic} | ${s.title} | ${s.pri} | ${s.pts} | ${STATUS_ICON[statusOf(s)]} |\n`;
    md += `\n`;
  }
  outputs.set(join(planDir, "sprints.md"), md);
}

// ── backlog.csv ──────────────────────────────────────────────────────────────────────────────
{
  const cell = (v) => `"${String(v).replace(/"/g, '""')}"`;
  const rows = [
    [
      "ID",
      "Title",
      "Epic",
      "Epic Name",
      "Sprint",
      "Status",
      "Priority",
      "Points",
      "User Story",
      "Acceptance Criteria",
      "Spec Refs",
      "Depends On",
      "Labels",
    ],
  ];
  for (const s of stories) {
    rows.push([
      s.id,
      s.title,
      s.epic,
      epicById.get(s.epic).name,
      s.sprint,
      statusOf(s),
      s.pri,
      s.pts,
      `As a ${s.as}, I want ${s.want}, so that ${s.so}.`,
      s.ac.map((a) => `- ${a}`).join("\n"),
      s.refs.join(", "),
      s.deps.join(", "),
      `story;epic:${s.epic};priority:${s.pri.toLowerCase()};release:${release.version}`,
    ]);
  }
  outputs.set(
    join(planDir, "backlog.csv"),
    `${rows.map((r) => r.map(cell).join(",")).join("\n")}\n`,
  );
}

// ── Write or check ───────────────────────────────────────────────────────────────────────────
let stale = 0;
for (const [path, content] of outputs) {
  const rel = relative(repoRoot, path);
  if (check) {
    const current = existsSync(path) ? await readFile(path, "utf8") : null;
    if (current !== content) {
      stale++;
      console.error(`✖ stale: ${rel}`);
    }
  } else {
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, content);
    console.log(`✔ ${rel}`);
  }
}
for (const w of warnings) console.warn(`⚠ ${w}`);
console.log(
  `\n${stories.length} stories · ${total} committed pts · ${donePts(committed)} done · ${sprints.length - 1} sprints · ` +
    sprints
      .filter((s) => s.id !== "STRETCH")
      .map((s) => `${s.id}:${load.get(s.id)}`)
      .join(" "),
);
if (check && stale) {
  console.error(`\n${stale} generated file(s) are stale. Run \`pnpm planning:build\`.`);
  process.exit(1);
}
